FILES = {'RUN5_mk_run5.py': '"""RUN5 generator (Grok, green_regular_character lane). Reads upstream files fetched at pin\n40e56bab026552e089d7afcfeff08d2defb9c005 into /workspace/rh_green_up and writes GreenCompanion/Run5.lean.\nTextual operations only: slice proof bodies verbatim, rename upstream dependency references to hypotheses\nwhose Prop-def text is the exact upstream statement (sliced from the *Statement.lean files)."""\nU = "/workspace/rh_green_up/src/Development/AbelianVarietyTheory/"\nL = "/workspace/rh_green_lean/GreenCompanion/"\nCT = "Proofs/CharacterTheory/"; FM = "Proofs/FlagMeasures/"\ndef rd(p): return open(U + p).read()\ndef body(p, ns):\n    t = rd(p); a = t.index("namespace " + ns + "\\n") + len("namespace " + ns + "\\n"); b = t.rindex("end " + ns)\n    return t[a:b].strip("\\n") + "\\n"\ndef stmt(p, name):\n    t = rd(p); key = "theorem _root_.GlobalTheory.T." + name + " : "\n    a = t.index(key) + len(key); b = t.index(" := by", a)\n    return t[a:b]\ndef sub(t, pairs):\n    for x, y in pairs:\n        assert x in t, x\n        t = t.replace(x, y)\n    return t\n\ncyc = stmt(CT + "FinsumCardCyclicVectorsInvariantSubspacesStatement.lean", "finsum_card_cyclic_vectors_invariant_subspaces")\nmcyc = stmt(CT + "EndomorphismMassOfCharpolyCardCyclicVectorsStatement.lean", "endomorphismMassOfCharpoly_card_cyclic_vectors")\nmconj = stmt(FM + "MirabolicConjInvariantEqSumInducedDerivativesStatement.lean", "mirabolicConjInvariant_eq_sum_induced_derivatives")\nmind = stmt(FM + "MirabolicInductionBlockDiagEqHarishChandraGelfanStatement.lean", "mirabolicInduction_blockDiag_eq_harishChandra_gelfandGraev")\ndcls = stmt(FM + "IsClassFunctionBernsteinZelevinskyDerivativeStatement.lean", "isClassFunction_bernsteinZelevinskyDerivative")\n\nexconj = body(CT + "ExistsConjEqAddOfIsCoprime.lean", "GlobalTheory.CuspGL")\neqz = body(CT + "EqZeroOfNotPrimary.lean", "GlobalTheory.CuspGL")\ncanc = body(CT + "MonicFactorizationConvolutionCancelOfOne.lean", "GlobalTheory.CuspGL.ConvCancel")\nmurec = sub(body(CT + "CharpolyEndomorphismDensityGLRecursion.lean", "GlobalTheory.CuspGL"), [\n    ("theorem mu_rec : ", "theorem mu_rec (hParMass : ParMassPart) (hCyc : CycSumPart) (hMC : MassCycPart) : "),\n    ("  intro F _ _ P hP\\n", "  unfold ParMassPart at hParMass\\n  unfold CycSumPart at hCyc\\n  unfold MassCycPart at hMC\\n  intro F _ _ P hP\\n"),\n    ("GlobalTheory.T.endomorphismMass_mul_parabolic_induction_trivial", "hParMass"),\n    ("GlobalTheory.T.finsum_card_cyclic_vectors_invariant_subspaces", "hCyc"),\n    ("GlobalTheory.T.endomorphismMassOfCharpoly_card_cyclic_vectors", "hMC")])\nmir = sub(body(FM + "MirabolicClassFunBlockDiagonalEqSumDerivatives.lean", "GlobalTheory.GLm"), [\n    ("theorem mirClass_diag1_eq_sum : ", "theorem mirClass_diag1_eq_sum (hMConj : MirConjPart) (hMInd : MirIndPart) (hDCls : DerClassPart) : "),\n    ("GlobalTheory.T.mirabolicConjInvariant_eq_sum_induced_derivatives", "hMConj"),\n    ("GlobalTheory.T.mirabolicInduction_blockDiag_eq_harishChandra_gelfandGraev", "hMInd"),\n    ("GlobalTheory.T.isClassFunction_bernsteinZelevinskyDerivative", "hDCls")])\nim = rd("Definitions/SemilocalFrames/IsMirClass.lean")\na = im.index("def indR "); b = im.index("\\n\\n", a)\nindR = im[a:b] + "\\n"\n\nout = f"""/-\nGreen lane RUN5 companion (Grok, 2026-11-24). Generated by RUN5_mk_run5.py from upstream\nleanprover-community/riemann-hypothesis @ 40e56bab026552e089d7afcfeff08d2defb9c005:\n  Proofs/CharacterTheory/EqZeroOfNotPrimary.lean            (CuspGL.eq_zero_of_not_primary, helper)\n  Proofs/CharacterTheory/ExistsConjEqAddOfIsCoprime.lean    (its in-repo dependency, whole body)\n  Proofs/CharacterTheory/MonicFactorizationConvolutionCancelOfOne.lean (CuspGL.ConvCancel.conv_cancel)\n  Proofs/CharacterTheory/CharpolyEndomorphismDensityGLRecursion.lean   (CuspGL.mu_rec and helpers)\n  Proofs/FlagMeasures/MirabolicClassFunBlockDiagonalEqSumDerivatives.lean (GLm.mirClass_diag1_eq_sum)\n  Definitions/SemilocalFrames/IsMirClass.lean               (def indR, verbatim)\nProof bodies verbatim; remaining upstream dependencies are hypotheses whose Prop-def text is the exact\nupstream statement. Definitions come from GreenCompanion.CuspGLRun4 / GreenCompanion.SumWhGG (verbatim\nupstream definitions, earlier runs). No sorry, no axiom.\n-/\nimport GreenCompanion.SumWhGG\nimport GreenCompanion.CuspGLRun4\n\nnoncomputable section\nopen Polynomial\n\nnamespace GreenCompanion\n\nsection CuspPart\nopen CuspGL\n\n/-- exact statement of upstream `GlobalTheory.T.finsum_card_cyclic_vectors_invariant_subspaces`. -/\ndef CycSumPart : Prop := {cyc}\n/-- exact statement of upstream `GlobalTheory.T.endomorphismMassOfCharpoly_card_cyclic_vectors`. -/\ndef MassCycPart : Prop := {mcyc}\n\nnamespace CuspGL\n\n{exconj}\n{eqz}\nnamespace ConvCancel\n\n{canc}\nend ConvCancel\n\n{murec}\nend CuspGL\n\n/-- RUN4 leaf `T.classFn_eq_zero_of_charpoly_not_irreducible_pow` (`NotPrimaryPart`), now unconditional. -/\ntheorem notPrimaryPart_holds : NotPrimaryPart := CuspGL.eq_zero_of_not_primary\n/-- RUN4 leaf `T.monicFactorizationConvolution_cancel_of_one` (`CancelPart`), now unconditional. -/\ntheorem cancelPart_holds : CancelPart := CuspGL.ConvCancel.conv_cancel\n/-- RUN4 leaf `T.charpolyEndomorphismDensityGL_recursion` (`MuRecPart`) from its three upstream deps. -/\ntheorem muRecPart_of_deps (hParMass : ParMassPart) (hCyc : CycSumPart) (hMC : MassCycPart) : MuRecPart :=\n  CuspGL.mu_rec hParMass hCyc hMC\n/-- RUN3 `TorusPart` (= `T.invertibleEndInnerProduct_rootPowerSum_eq_torusSum`), now unconditional. -/\ntheorem torusPart_holds : TorusPartR3 := torusPart_of_deps notPrimaryPart_holds\n\nend CuspPart\n\nsection MirS\nopen scoped Classical\nvariable {{g : ℕ}} [Fact g.Prime]\n\n{indR}\nend MirS\n\nopen scoped Classical in\n/-- exact statement of upstream `GlobalTheory.T.mirabolicConjInvariant_eq_sum_induced_derivatives`. -/\ndef MirConjPart : Prop := {mconj}\nopen scoped Classical in\n/-- exact statement of upstream `GlobalTheory.T.mirabolicInduction_blockDiag_eq_harishChandra_gelfandGraev`. -/\ndef MirIndPart : Prop := {mind}\nopen scoped Classical in\n/-- exact statement of upstream `GlobalTheory.T.isClassFunction_bernsteinZelevinskyDerivative`. -/\ndef DerClassPart : Prop := {dcls}\n\nnamespace GLm\nopen scoped Classical\n\n{mir}\nend GLm\n\n/-- RUN4 leaf `T.mirabolicClassFun_blockDiagonal_eq_sum_derivatives` (`MirPart`) from its three upstream deps. -/\ntheorem mirPart_of_deps (hMConj : MirConjPart) (hMInd : MirIndPart) (hDCls : DerClassPart) : MirPart :=\n  GLm.mirClass_diag1_eq_sum hMConj hMInd hDCls\n\n/-- RUN3 `SumWhGGPart` (= upstream `GLm.GGSum.sum_wh_gg`) from the current leaves (RUN4 + RUN5). -/\ntheorem sumWhGGPart_of_leaves (hWJ : WJPart) (hWhMul : WhMulPart) (hBZ : BZPart) (hMConj : MirConjPart)\n    (hMInd : MirIndPart) (hDCls : DerClassPart) : SumWhGGPart :=\n  sumWhGGPart_of_deps hWJ hWhMul hBZ (mirPart_of_deps hMConj hMInd hDCls)\n\n/-- RUN3 `MassPart` (= upstream `T.endomorphismMass_mobiusInverse_monic_eq`) from the current leaves:\n`CancelPart` is now proved and `MuRecPart` is replaced by its two cyclic-vector deps (plus `ParMassPart`). -/\ntheorem massPart_of_leaves (hConj : ConjPart) (hLog : LogConvPart) (hParMass : ParMassPart) (hPsiSum : PsiSumPart)\n    (hMassEq : MassEqPart) (hCyc : CycSumPart) (hMC : MassCycPart) : MassPartR3 :=\n  massPart_of_deps hConj (muRecPart_of_deps hParMass hCyc hMC) hLog hParMass hPsiSum cancelPart_holds hMassEq\n\nend GreenCompanion\n\n#print axioms GreenCompanion.CuspGL.eq_zero_of_not_primary\n#print axioms GreenCompanion.CuspGL.ConvCancel.conv_cancel\n#print axioms GreenCompanion.CuspGL.mu_rec\n#print axioms GreenCompanion.GLm.mirClass_diag1_eq_sum\n#print axioms GreenCompanion.notPrimaryPart_holds\n#print axioms GreenCompanion.cancelPart_holds\n#print axioms GreenCompanion.muRecPart_of_deps\n#print axioms GreenCompanion.torusPart_holds\n#print axioms GreenCompanion.mirPart_of_deps\n#print axioms GreenCompanion.sumWhGGPart_of_leaves\n#print axioms GreenCompanion.massPart_of_leaves\n"""\nopen(L + "Run5.lean", "w").write(out)\nprint("wrote", L + "Run5.lean", len(out))\n', 'RUN5_green_exact_checks.py': '"""RUN5 exact finite checks (green_regular_character lane). Exact integer / Fraction arithmetic only.\nSmall-case illustrations over F_q (q prime), computed directly from the upstream definitions; they are not proofs\nof the general Lean declarations.\n (A) eq_zero_of_not_primary: on End(F_q^n), solve exactly for ALL class functions phi that are primitive\n     (for every invariant A with 0 < A < V and every g preserving A: sum_{h in nilRad A} phi(g+h) = 0) and check\n     every such phi vanishes at every g whose charpoly is not f^m (f monic irreducible, m > 0).\n (B) leaf finsum_card_cyclic_vectors_invariant_subspaces: sum over g-invariant W of #(g|W-cyclic vectors of W) = q^dim V.\n (C) leaf endomorphismMassOfCharpoly_card_cyclic_vectors: sum over g with charpoly D of #cyclic vectors = |GL_n|.\n (D) the triangular structure conv_cancel\'s induction uses: for monic P, (P,1) is the only factorisation pair with first factor of degree deg P."""\nfrom fractions import Fraction\nfrom itertools import product\n\ndef pmul(a, b, q):\n    r = [0] * (len(a) + len(b) - 1)\n    for i, x in enumerate(a):\n        for j, y in enumerate(b): r[i + j] = (r[i + j] + x * y) % q\n    return tuple(r)\ndef monics(d, q):\n    for c in product(range(q), repeat=d): yield tuple(c) + (1,)\ndef is_irred(f, q):\n    d = len(f) - 1\n    return all(pmul(a, b, q) != f for e in range(1, d // 2 + 1) for a in monics(e, q) for b in monics(d - e, q))\ndef is_primary(P, q):\n    d = len(P) - 1\n    for e in range(1, d + 1):\n        if d % e: continue\n        for f in monics(e, q):\n            if not is_irred(f, q): continue\n            t = (1,)\n            for _ in range(d // e): t = pmul(t, f, q)\n            if t == P: return True\n    return False\ndef matmul(A, B, q):\n    n = len(A); return tuple(tuple(sum(A[i][k] * B[k][j] for k in range(n)) % q for j in range(n)) for i in range(n))\ndef madd(A, B, q): return tuple(tuple((A[i][j] + B[i][j]) % q for j in range(len(A))) for i in range(len(A)))\ndef det(M, q):\n    n = len(M)\n    if n == 0: return 1\n    return sum((-1) ** j * M[0][j] * det([r[:j] + r[j+1:] for r in M[1:]], q) for j in range(n)) % q\ndef mats(n, q): return [tuple(tuple(c[i*n:(i+1)*n]) for i in range(n)) for c in product(range(q), repeat=n*n)]\ndef vecs(n, q): return list(product(range(q), repeat=n))\ndef apply(M, v, q): return tuple(sum(M[i][j] * v[j] for j in range(len(v))) % q for i in range(len(M)))\ndef span(gens, n, q):\n    S = {tuple([0] * n)}\n    for g in gens:\n        S |= {tuple((s[i] + c * g[i]) % q for i in range(n)) for s in S for c in range(q)}\n    return frozenset(S)\ndef subspaces(n, q):\n    V = vecs(n, q); out = set()\n    for k in range(n + 1):\n        for gens in product(V, repeat=k): out.add(span(gens, n, q))\n    return out\ndef invariant(M, W, q): return all(apply(M, w, q) in W for w in W)\n\ndef charpoly_any(M, q):  # works for q <= n too: char poly via Faddeev-free expansion over polynomial ring\n    n = len(M)\n    if n == 0: return (1,)\n    def pdet(A):  # A: matrix of polynomials (tuples), Laplace expansion\n        m = len(A)\n        if m == 1: return A[0][0]\n        acc = (0,)\n        for j in range(m):\n            minor = [r[:j] + r[j+1:] for r in A[1:]]\n            t = pmul(A[0][j], pdet(minor), q)\n            if j % 2: t = tuple((-c) % q for c in t)\n            L = max(len(acc), len(t)); acc = tuple(((acc[i] if i < len(acc) else 0) + (t[i] if i < len(t) else 0)) % q for i in range(L))\n        while len(acc) > 1 and acc[-1] == 0: acc = acc[:-1]\n        return acc\n    A = [[((-M[i][j]) % q, 1) if i == j else ((-M[i][j]) % q,) for j in range(n)] for i in range(n)]\n    return pdet(A)\n\ndef rref_nullspace(rows, nvars):\n    rows = [list(map(Fraction, r)) for r in rows]; piv = []; r = 0\n    for c in range(nvars):\n        p = next((i for i in range(r, len(rows)) if rows[i][c] != 0), None)\n        if p is None: continue\n        rows[r], rows[p] = rows[p], rows[r]; pv = rows[r][c]; rows[r] = [x / pv for x in rows[r]]\n        for i in range(len(rows)):\n            if i != r and rows[i][c] != 0:\n                f = rows[i][c]; rows[i] = [a - f * b for a, b in zip(rows[i], rows[r])]\n        piv.append(c); r += 1\n    free = [c for c in range(nvars) if c not in piv]; basis = []\n    for fc in free:\n        v = [Fraction(0)] * nvars; v[fc] = Fraction(1)\n        for i, pc in enumerate(piv): v[pc] = -rows[i][fc]\n        basis.append(v)\n    return basis\n\ndef check_A(q, n):\n    Ms = mats(n, q); GL = [M for M in Ms if det(M, q) != 0]\n    cls = {}; reps = []\n    for M in Ms:\n        if M in cls: continue\n        k = len(reps); reps.append(M)\n        for Pm in GL:\n            Pi = next(X for X in GL if matmul(Pm, X, q) == tuple(tuple(int(i == j) for j in range(n)) for i in range(n)))\n            cls[matmul(matmul(Pm, M, q), Pi, q)] = k\n    subs = [W for W in subspaces(n, q) if 1 < len(W) < q ** n]\n    rows = []\n    for A in subs:\n        nil = [h for h in Ms if all(apply(h, v, q) in A for v in vecs(n, q)) and all(apply(h, a, q) == tuple([0]*n) for a in A)]\n        for g in Ms:\n            if not invariant(g, A, q): continue\n            row = [0] * len(reps)\n            for h in nil: row[cls[madd(g, h, q)]] += 1\n            rows.append(row)\n    basis = rref_nullspace(rows, len(reps))\n    nonprim = [k for k, M in enumerate(reps) if not is_primary(charpoly_any(M, q), q)]\n    bad = sum(1 for v in basis for k in nonprim if v[k] != 0)\n    print(f"(A) q={q} n={n}: {len(reps)} conjugacy classes in End, {len(rows)} primitivity equations, "\n          f"primitive class functions dim = {len(basis)}, non-primary classes = {len(nonprim)}, nonzero values there = {bad}")\n\ndef cyclic_count(M, W, q, n):\n    # vectors w in W generating W as F[g]-module (W invariant under M)\n    cnt = 0\n    for w in W:\n        S = span([w], n, q); cur = w\n        for _ in range(n):\n            cur = apply(M, cur, q); S = span(list(S) + [cur], n, q) if cur not in S else S\n        if S == W: cnt += 1\n    return cnt\ndef check_B(q, n):\n    subs = list(subspaces(n, q)); bad = 0; Ms = mats(n, q)\n    for M in Ms:\n        tot = sum(cyclic_count(M, W, q, n) for W in subs if invariant(M, W, q))\n        if tot != q ** n: bad += 1\n    print(f"(B) q={q} n={n}: {len(Ms)} endomorphisms, mismatches = {bad}")\ndef check_C(q, n):\n    Ms = mats(n, q); V = frozenset(vecs(n, q)); glc = sum(1 for M in Ms if det(M, q) != 0)\n    by = {}\n    for M in Ms:\n        P = charpoly_any(M, q); by[P] = by.get(P, 0) + cyclic_count(M, V, q, n)\n    allP = list(monics(n, q)); bad = sum(1 for P in allP if by.get(P, 0) != glc)\n    print(f"(C) q={q} n={n}: |GL|={glc}, {len(allP)} monic D, mismatches = {bad}")\ndef check_D(q, dmax):\n    bad = 0; cnt = 0\n    for d in range(1, dmax + 1):\n        for P in monics(d, q):\n            cnt += 1\n            pairs = [(D, E) for e in range(d + 1) for D in monics(d - e, q) for E in monics(e, q) if pmul(D, E, q) == P]\n            top = [x for x in pairs if len(x[0]) - 1 == d]\n            if top != [(P, (1,))]: bad += 1\n    print(f"(D) q={q} deg<={dmax}: {cnt} monic P, factorisation pairs with deg D = deg P other than (P,1): {bad}")\n\nif __name__ == "__main__":\n    for q, n in [(2, 2), (3, 2), (2, 3)]: check_A(q, n)\n    for q, n in [(2, 2), (3, 2), (2, 3)]: check_B(q, n)\n    for q, n in [(2, 2), (3, 2), (5, 2), (2, 3)]: check_C(q, n)\n    for q, d in [(2, 4), (3, 3)]: check_D(q, d)\n'}
for n, c in FILES.items():
    open(n, "w").write(c)
    print("wrote", n)
